"""Assemble previews, a complete mapping report and the delivery ZIP."""
from pathlib import Path
import json, zipfile, math
from PIL import Image, ImageDraw, ImageFont
ROOT=Path(__file__).resolve().parent;WORK=ROOT/'recruit_v03_work';OUT=ROOT/'Recruit_v03_previews'
rig=json.loads((WORK/'rig_validation.json').read_text())
engine=json.loads((WORK/'godot_validation.json').read_text())
glb=json.loads((WORK/'glb_validation.json').read_text())
assert engine['passed'] and glb['passed']
fontpath=Path('C:/Windows/Fonts/arial.ttf')
font=ImageFont.truetype(str(fontpath),23)
small=ImageFont.truetype(str(fontpath),19)
def caption(image,text):
    image=image.convert('RGB');draw=ImageDraw.Draw(image);draw.rectangle((0,0,image.width,35),fill=(18,24,27));draw.text((12,6),text,font=small,fill=(245,244,230));return image
for label,clip in [('Idle','Idle_Loop'),('Walk','Walk_Loop'),('Run_Sprint','Sprint_Loop'),('Walk_hold','Walk_Loop')]:
    names=sorted((WORK/'motion_frames').glob(label+'_[0-9][0-9].png'))
    assert len(names)==12,(label,len(names))
    frames=[caption(Image.open(p),{'Idle':'Idle — UAL','Walk':'Walk — UAL','Run_Sprint':'Sprint — UAL','Walk_hold':'Walk + apoio opcional com duas mãos'}[label]) for p in names]
    frames=[frame.quantize(colors=192,method=Image.Quantize.MEDIANCUT) for frame in frames]
    duration=round(engine['clips'][clip]['length_s']*1000/12)
    frames[0].save(OUT/(label+'.gif'),save_all=True,append_images=frames[1:],duration=duration,loop=0,disposal=2,optimize=False)
sheet=Image.new('RGB',(1200,880),(18,24,27));draw=ImageDraw.Draw(sheet)
draw.text((20,12),'Recruit v03 · 53 ossos UAL · 104 peças · 4.000 triângulos',font=font,fill=(245,244,230))
for index,(name,label) in enumerate([('base_frente','T-pose · frente'),('base_lado','T-pose · lado'),('base_tras','T-pose · trás'),('Idle','Idle_Loop'),('Walk','Walk_Loop'),('Run_Sprint','Sprint_Loop')]):
    im=Image.open(OUT/(name+'.png')).convert('RGB').resize((400,400),Image.Resampling.LANCZOS)
    x=(index%3)*400;y=50+(index//3)*415;sheet.paste(im,(x,y));draw.text((x+12,y+377),label,font=small,fill=(255,250,230))
sheet.save(OUT/'comparacao_v03.jpg',quality=94)
report=[]
def add(text=''):report.append(text)
add('# Recruit v03 — rig UAL e validação')
