for key,value in [
('Blender',rig['blender']),('Godot real',engine['godot_version']['string']),('Nomes/pais dos ossos','53/53, correspondência exata'),('Meshes rígidos / materiais / triângulos','104 / 35 / 4.000'),('Vértices no GLB','8.402; duplicações por normais planas, sem aumento de triângulos'),('Altura no GLB',f"{glb['height_m']:.9f} m"),('Paleta e propriedades PBR','Iguais às do GLB de origem'),('Animações no GLB principal','0'),('Topologia Blender','Todas as peças fechadas, arestas manifold, volume positivo'),('Matrizes de bind',f"Erro máximo {glb['maximum_bind_matrix_error']:.3g}"),('Orientação de rest Blender',f"Erro máximo {rig['maximum_rest_orientation_error_rad']:.3g} rad"),('Clips testados no Godot',f"46; {sum(c['samples'] for c in engine['clips'].values())} amostras"),('Idle / Walk / Sprint','17 amostras por clip, mais teste do apoio de duas mãos'),('Escala durante animação',f"Erro máximo {engine['maximum_bone_scale_error']:.3g}"),('Ligação do Muzzle durante animação',f"Erro máximo {engine['maximum_muzzle_attachment_error_m']:.3g} m"),('Apoio da mão esquerda',f"Erro máximo {engine['maximum_hold_contact_error_m']:.3g} m"),('Carregador em execução',engine['loader_playback']),('SHA-256 dos originais','Preservados')]:add(f'| {key} | {value} |')
add('')
add('Foram verificadas poses finitas, ausência de escala indesejada, pesos, ossos, pais e ligação do Muzzle no motor real. Os renderizadores mostram a pose base de frente/lado/trás, três frames de locomoção e uma pose com apoio; há também quatro GIFs de 12 frames por ciclo. As imagens foram inspecionadas visualmente. Os testes numéricos de 46 clips não substituem uma revisão artística quadro a quadro de todos os movimentos.')
add('')
