files=[ROOT/name for name in ['Horde_Braker_Recruit_v03_rigged.glb','Horde_Braker_Recruit_v03_rigged.blend','Horde_Braker_Recruit_v03_relatorio.md','Recruit_v03.tscn','Recruit_UAL_compatible.tres','Recruit_UAL_loader.gd','Recruit_Rifle_Hold.gd','Recruit_Rifle_Hold_pose.json','rig_recruit_v03.py','recruit_render.py','render_recruit_v03_motion.py','validate_recruit_v03_glb.py','package_recruit_v03.py']]
